class Main {
    static class Box {
        // 이 값은 객체에 들어 있어요.
        int value;
    }
    static int read(Box item) {
        // 어느 객체인지 직접 적어야 해요.
        return value;
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Box item = new Box();
        item.value = n;
        // static 메서드에 읽을 객체를 전달해요.
        System.out.println(read(item));
    }
}
